import * as pulumi from "@pulumi/pulumi";
import * as dynatrace from "@pulumiverse/dynatrace";

export = async () => {
    const TERRAFORM_SAMPLE = new dynatrace.AzureCredentials("TERRAFORM_SAMPLE", {
        active: false,
        appId: "ABCDE",
        autoTagging: true,
        directoryId: "ABCDE",
        label: "TERRAFORM_SAMPLE",
        key: "aaaa",
        monitorOnlyTaggedEntities: true,
        monitorOnlyTagPairs: [{
            name: "string",
            value: "string",
        }],
    });
    const supportedServices = await dynatrace.getAzureSupportedServices({
        excepts: ["AZURE_STORAGE_ACCOUNT"],
    });
    const tERRAFORMSAMPLEServices: dynatrace.AzureService[] = [];
    for (const range of Object.entries(supportedServices.services).sort().map(([k, v]) => ({key: k, value: v}))) {
        tERRAFORMSAMPLEServices.push(new dynatrace.AzureService(`TERRAFORM_SAMPLE_services-${range.key}`, {
            credentialsId: TERRAFORM_SAMPLE.id,
            useRecommendedMetrics: true,
            name: range.key,
        }));
    }
}
