      source = "pulumi/dynatrace"
    }
  }
}

data "dynatrace_synthetic_location" "location" {
  name = "Location"
}
data "dynatrace_application" "webApplication" {
  name = "Web Application"
}

resource "dynatrace_credentials" "credentials_vault" {
  lifecycle {
    create_before_destroy = true
  }
  name        = "#name#"
  description = "my credentials vault"
  scopes      = ["SYNTHETIC"]
  username    = "username"
  password    = "password"
}
resource "dynatrace_browser_monitor" "monitor" {
  lifecycle {
    create_before_destroy = true
  }
  name                   = "#name#"
  frequency              = 15
  locations              = [data.dynatrace_synthetic_location.location.id]
  manually_assigned_apps = [data.dynatrace_application.webApplication.id]
  anomaly_detection {
    loading_time_thresholds {
      enabled = true
    }
    outage_handling {
      global_outage  = true
      retry_on_error = true
      global_outage_policy {
        consecutive_runs = 1
      }
    }
  }
  key_performance_metrics {
    load_action_kpm = "VISUALLY_COMPLETE"
    xhr_action_kpm  = "VISUALLY_COMPLETE"
  }
  script {
    type = "clickpath"
    configuration {
      bypass_csp = true
