        description = "Add warning flag"
        matcher     = "matchesPhrase(record.name, \"Warning\")"
        sample_data = "{\n  \"record.name\": \"Warning record\" \n}"
        fields_add {
          fields {
            field {
              name       = "is_warning"
              value      = "true"
              value_type = "boolean"
            }
          }
        }
        enabled = true
      }
      processor {
        type        = "fieldsRemove"
