              source_field_name = "dt.cost.costcenter"
            }
            dimension {
              extraction_type   = "field"
              strategy          = "equals"
              source_field_name = "dt.cost.product"
            }
            dimension {
              extraction_type   = "field"
              strategy          = "equals"
              source_field_name = "dt.security_context"
            }
            dimension {
              extraction_type        = "field"
              strategy               = "equals"
              source_field_name      = "record.category"
              destination_field_name = "warning_category"
            }
          }
        }
        enabled = true
      }
    }
  }
  security_context {
    processors {
